import { expect, it } from 'vitest';
import { classifyAliases, aliasChangeDialog, pictureSelection, historicalHandleAvailability, pictureImportPollInterval, shouldClearOwnerProfile } from '@/features/profile-management';
it('classifies aliases without showing active aliases again in history', () => {
  const profile={aliases:[{handle:'old'},{handle:'expiring',expiresAt:'soon'}],historicalHandles:[{handle:'old'},{handle:'recent'}]};
  const result=classifyAliases(profile);
  expect(result.retained.map(a=>a.handle)).toEqual(['old']);
  expect(result.expiring.map(a=>a.handle)).toEqual(['expiring']);
  expect(result.historical.map(a=>a.handle)).toEqual(['recent']);
  expect(result.summary).toBe('1 retained · 1 expiring');
  expect(classifyAliases({}).summary).toBe('No previous handles');
});
it('describes each selected alias action', () => {
  const command={action:'expire' as const,handle:'old',expectedVersion:3};
  expect(aliasChangeDialog(command,'current')).toMatchObject({title:'Expire alias now?',button:'Expire now'});
  for(const action of ['schedule','keep','reactivate'] as const) expect(aliasChangeDialog({...command,action},'current').description).toContain('@old');
});
it('rejects unsupported pictures, permits large local sources, and handles deselection', () => {
  expect(pictureSelection({type:'image/gif',size:1},['image/jpeg','image/png','image/webp']).error).toContain('JPEG');
  expect(pictureSelection({type:'image/png',size:6000000},['image/jpeg','image/png','image/webp']).selected).not.toBeNull();
  const file={type:'image/webp',size:10};expect(pictureSelection(file,['image/jpeg','image/png','image/webp'])).toEqual({selected:file,error:null});
  expect(pictureSelection(undefined,['image/jpeg','image/png','image/webp'])).toEqual({selected:null,error:null});
});
it('prioritizes expired history and maps unavailable reasons', () => {
  expect(historicalHandleAvailability(5,'claimed',5)).toContain('recent history');
  expect(historicalHandleAvailability(10,'claimed',5)).toContain('claimed');
  expect(historicalHandleAvailability(10,'alias-limit',5)).toContain('limit');
  expect(historicalHandleAvailability(10,null,5)).toBeNull();
});
it('pauses import polling during writes and purges only resolved session transitions', () => {
  expect(pictureImportPollInterval('pending',false)).toBe(5000);
  expect(pictureImportPollInterval('retrying',true)).toBe(false);
  expect(pictureImportPollInterval('complete',false)).toBe(false);
  expect(shouldClearOwnerProfile('a',null,false)).toBe(false);
  expect(shouldClearOwnerProfile('a','b',true)).toBe(true);
  expect(shouldClearOwnerProfile(null,'a',true)).toBe(false);
  expect(shouldClearOwnerProfile('a',null,true)).toBe(true);
});

export type { AliasCommand, ProfileCommandAvailability, ProfileQueryOwnership } from './contract';
export {
  classifyAliases,
  aliasChangeDialog,
  historicalHandleAvailability,
  aliasConflictMessage,
} from './aliases';
export { pictureSelection, pictureImportPollInterval, shouldClearOwnerProfile } from './pictures';

import type { AliasCommand } from './contract';
export function aliasChangeDialog(command: AliasCommand | null, currentHandle: string) {
  const handle = command?.handle ?? '';
  switch (command?.action) {
    case 'keep':
      return {
        title: 'Keep this alias?',
        description: `Cancel the scheduled removal of @${handle}. It will keep redirecting and use one retained alias slot. Your current Handle will stay @${currentHandle}, and its change cooldown will stay the same.`,
        button: 'Keep alias',
      };
    case 'reactivate':
      return {
        title: 'Reactivate historical Handle?',
        description: `@${handle} will redirect to your Profile and use one retained alias slot. Your current Handle will stay @${currentHandle}, and its change cooldown will stay the same.`,
        button: 'Reactivate alias',
      };
    case 'expire':
      return {
        title: 'Expire alias now?',
        description: `@${handle} will stop redirecting immediately. This Handle will become available for another User to claim. Existing links using this handle will no longer lead to your Profile.`,
        button: 'Expire now',
      };
    default:
      return {
        title: 'Schedule alias removal?',
        description: `@${handle} will expire 24 hours after you confirm. This profile handle will redirect until it expires, then stop redirecting to your Profile. It stops counting toward your retained limit immediately.`,
        button: 'Schedule removal',
      };
  }
}

export function classifyAliases<
  Alias extends { handle: string; expiresAt?: string | null },
  History extends { handle: string },
>(profile: { aliases?: Alias[]; historicalHandles?: History[] }) {
  const retained = (profile.aliases ?? []).filter((alias) => !alias.expiresAt);
  const expiring = (profile.aliases ?? []).filter((alias) => alias.expiresAt);
  const historical = (profile.historicalHandles ?? []).filter(
    (entry) => !profile.aliases?.some((alias) => alias.handle === entry.handle)
  );
  const summary =
    retained.length || expiring.length
      ? `${retained.length} retained${expiring.length ? ` · ${expiring.length} expiring` : ''}`
      : historical.length
        ? `${historical.length} historical`
        : 'No previous handles';
  return { retained, expiring, historical, summary };
}
export function historicalHandleAvailability(
  eligibleUntil: number,
  reason: 'claimed' | 'alias-limit' | null,
  now: number
): string | null {
  if (eligibleUntil <= now)
    return 'This Handle is no longer in your recent history. Refresh aliases.';
  if (reason === 'claimed') return 'Another Profile has claimed this Handle.';
  if (reason === 'alias-limit') return 'Your retained-alias limit is full.';
  return null;
}
export function aliasConflictMessage(action: AliasCommand['action']): string {
  const verbs = {
    schedule: 'scheduling',
    expire: 'expiring',
    reactivate: 'reactivating',
    keep: 'canceling removal',
  };
  return `Your Profile changed elsewhere. Refresh aliases before ${verbs[action]} again.`;
}

export function pictureSelection<T extends { type: string; size: number }>(
  picture: T | undefined,
  acceptedSourceFormats: readonly string[]
): { selected: T | null; error: string | null } {
  if (picture && !acceptedSourceFormats.includes(picture.type))
    return {
      selected: null,
      error: `Choose a ${new Intl.ListFormat('en', { type: 'disjunction' }).format(acceptedSourceFormats.map((format) => (format === 'image/webp' ? 'WebP' : format.replace('image/', '').toUpperCase())))} picture.`,
    };
  return { selected: picture ?? null, error: null };
}
export function pictureImportPollInterval(
  status: string | undefined,
  writing: boolean
): number | false {
  return !writing && (status === 'pending' || status === 'retrying') ? 5000 : false;
}
export function shouldClearOwnerProfile(
  previous: string | null,
  active: string | null,
  loaded: boolean
): boolean {
  return loaded && (!active || Boolean(previous && previous !== active));
}

export interface AliasCommand {
  action: 'schedule' | 'expire' | 'reactivate' | 'keep';
  handle: string;
  expectedVersion: number;
}

/** Live shared command availability, without copying request state into an editor. */
export interface ProfileCommandAvailability {
  isBusy: () => boolean;
  subscribe: (listener: () => void) => () => void;
}

/** Identity changes when the saved owner query is removed or recreated. */
export interface ProfileQueryOwnership {
  getIdentity: () => object | undefined;
  subscribe: (listener: () => void) => () => void;
}

